from typing import Any, Dict, List

class DocumentRequest:
    def __init__(self, document_type: str, document_content: bytes):
        self.document_type = document_type
        self.document_content = document_content

    def to_dict(self) -> Dict[str, Any]:
        return {
            'document_type': self.document_type,
            'document_content': self.document_content
        }

class DocumentResponse:
    def __init__(self, extracted_fields: Dict[str, Any], confidence_scores: Dict[str, float]):
        self.extracted_fields = extracted_fields
        self.confidence_scores = confidence_scores

    def to_dict(self) -> Dict[str, Any]:
        return {
            'extracted_fields': self.extracted_fields,
            'confidence_scores': self.confidence_scores
        }

def normalize_document_fields(extracted_fields: Dict[str, Any]) -> Dict[str, Any]:
    normalized_fields = {}
    for key, value in extracted_fields.items():
        normalized_fields[key.lower().replace(' ', '_')] = value
    return normalized_fields

import os
import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

# Configuration
AWS_REGION = os.getenv('AWS_REGION', 'us-west-2')

# Client
textract_client = boto3.client('textract', region_name=AWS_REGION)

def configure_textract_client(region=None):
    global textract_client
    if region:
        textract_client = boto3.client('textract', region_name=region)
    else:
        textract_client = boto3.client('textract')

def check_aws_credentials():
    try:
        boto3.client('sts').get_caller_identity()
    except (NoCredentialsError, PartialCredentialsError) as e:
        raise Exception('AWS credentials not configured: ' + str(e))

# Helper Utilities
def start_document_analysis(document_location, feature_types=['FORMS', 'TABLES']):
    response = textract_client.start_document_analysis(
        DocumentLocation=document_location,
        FeatureTypes=feature_types
    )
    return response

def get_document_analysis_result(job_id):
    response = textract_client.get_document_analysis(JobId=job_id)
    return response

import boto3

def validate_fields(document):
    comprehend = boto3.client('comprehend')
    try:
        response = comprehend.detect_sentiment(Text=document['text'], LanguageCode='en')
        sentiment = response['Sentiment']
        confidence_score = response['SentimentScore'][sentiment]
        if confidence_score < 0.5:
            return False, 'Low confidence score'
        else:
            return True, 'Validation passed'
    except Exception as e:
        return False, str(e)

import boto3

def extract_receipt_fields(receipt_image):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': receipt_image},
        FeatureTypes=['FORMS', 'TABLES']
    )
    merchant = None
    tax = None
    total = None
    items = []
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'Merchant' in block['Text']:
                merchant = block['Text'].replace('Merchant', '').strip()
            elif 'Tax' in block['Text']:
                tax = block['Text'].replace('Tax', '').strip()
            elif 'Total' in block['Text']:
                total = block['Text'].replace('Total', '').strip()
        elif block['BlockType'] == 'TABLE':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                        if child_block['BlockType'] == 'CELL':
                            items.append(child_block['Text'].strip())
    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }

import boto3

def extract_invoice_fields(document):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS']
    )
    vendor = None
    date = None
    total = None
    line_items = []
    for item in response.get('Blocks', []):
        if item['BlockType'] == 'KEY_VALUE_SET':
            if item['Text'] == 'Vendor':
                vendor = item['Relationships'][0]['Text']
            elif item['Text'] == 'Date':
                date = item['Relationships'][0]['Text']
            elif item['Text'] == 'Total':
                total = item['Relationships'][0]['Text']
        elif item['BlockType'] == 'LINE':
            line_items.append(item['Text'])
    return {
        'vendor': vendor,
        'date': date,
        'total': total,
        'line_items': line_items
    }
